const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Polygon(
    [
      [
        [-65, -15],
        [-65, -5],
        [-50, -5],
        [-50, -15]
      ]
    ],
    null,
    false
  ); // Southern Brazilian Amazon approximation

  const date2019_start = '2019-01-01';
  const date2019_end = '2019-12-31';
  const date2020_start = '2020-01-01';
  const date2020_end = '2020-12-31';

  const collectionId = 'NOAA/VIIRS/001/VNP14A1_NRT';
  const bandName = 'thermal_anomaly'; // Values indicate fire detections

  // 2. Data Acquisition & Check
  let collection2019 = ee.ImageCollection(collectionId)
    .filterDate(date2019_start, date2019_end)
    .filterBounds(geometry);

  let collection2020 = ee.ImageCollection(collectionId)
    .filterDate(date2020_start, date2020_end)
    .filterBounds(geometry);

  const size2019 = await collection2019.size().getInfo();
  const size2020 = await collection2020.size().getInfo();

  if (size2019 === 0 || size2020 === 0) {
    console.log(`2019 Images: ${size2019}`);
    console.log(`2020 Images: ${size2020}`);
    console.log("C1"); // Empty Collection
    return;
  }

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  // 3. Processing: Count fire pixels
  // Define a function to get fire pixel count for each image
  const getFirePixels = (image) => {
    // A thermal_anomaly value > 0 indicates a fire detection (even low confidence)
    // We count pixels where thermal_anomaly is 1 or greater (actual detection)
    return image.select(bandName).gt(0).rename('fire_detection');
  };

  const firePixels2019 = collection2019.map(getFirePixels);
  const firePixels2020 = collection2020.map(getFirePixels);

  // Sum all fire detections over the year for each collection
  // Use a sum reducer to count total fire-pixel-days.
  // Using a larger scale for faster computation.
  const scale = 5000; // VIIRS is approx 375m, using 5000m scale for efficiency
  const maxPixels = 1e10; // Allow more pixels

  const sumReducer = ee.Reducer.sum();

  const totalFireEvents2019 = await firePixels2019
    .sum() // Sums the 'fire_detection' band across all images
    .reduceRegion({
      reducer: sumReducer,
      geometry: geometry,
      scale: scale,
      maxPixels: maxPixels
    })
    .get('fire_detection')
    .getInfo();

  const totalFireEvents2020 = await firePixels2020
    .sum()
    .reduceRegion({
      reducer: sumReducer,
      geometry: geometry,
      scale: scale,
      maxPixels: maxPixels
    })
    .get('fire_detection')
    .getInfo();

  // 4. Calculation & Validation
  if (totalFireEvents2019 === null || isNaN(totalFireEvents2019) ||
      totalFireEvents2020 === null || isNaN(totalFireEvents2020)) {
    console.log("C3"); // Calculation Failure
    return;
  }

  // Check for C2 (No Valid Pixels) - if totalFireEvents is 0 after processing
  // It's a valid zero here, meaning no fires were detected, not "no valid pixels".
  // The reduceRegion would typically return null or throw an error if no pixels were valid.
  // Here, if it's 0, it means 0 fires were counted.

  console.log(`Total detected fire events in 2019: ${totalFireEvents2019}`);
  console.log(`Total detected fire events in 2020: ${totalFireEvents2020}`);

  // 5. Final Answer
  if (totalFireEvents2020 > totalFireEvents2019) {
    console.log("A"); // Yes, more fires in 2020
  } else {
    console.log("B"); // No, not more fires in 2020 (or equal)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
